const byId = Object.fromEntries(CONDITIONS.map((c) => [c.id, c]));
const label = (id) => (SYMPTOMS[id] ? SYMPTOMS[id][0] : id);

// Text passages so the offline search can also surface these curated entries.
function searchDocs() {
  return CONDITIONS.map((c) => ({
    id: `cl-${c.id}`, title: c.name, topic: 'overview', source: 'RuralDoc clinical guide',
    content: `${c.name}. Typical symptoms: ${Object.keys(c.syms).filter((k) => !k.startsWith('ctx_') && !k.startsWith('inj_')).map(label).join(', ')}. ${c.care} ${c.doc} Warning signs: ${c.red.join('; ')}.`,
  }));
}

module.exports = { SYMPTOMS, CONDITIONS, INJURY_FIRSTAID, byId, label, searchDocs };
